-- Policies, Help and the Children's Privacy Notice say plainly that Google sets third-party cookies
-- from books.google.com on our website, because LiteraryWorm uses the Google Books API: covers of
-- Google Books titles and the Google Books preview load from there. The Cookie Policy lists them like
-- Cloudflare's cookie. src/data/legalPages.json has the same. Each change applies only while the page
-- still has the built-in wording. Also What's new.

update public.legal_pages set sections = replace(sections::text, $lw$Some book covers from Google Books, the Google Books preview on some book pages (only when you open it), and the audiobook recordings streamed from the Internet Archive, load from those services. When your browser fetches them, those services may set or read their own cookies under their own policies. Blocking third-party cookies in your browser doesn't stop LiteraryWorm working.$lw$, $lw$Google Books cookies. Purpose: LiteraryWorm uses the Google Books API to find books and show their details. So the covers of books from Google Books, and the Google Books preview on some book pages (only when you open it), load in your browser from books.google.com, and Google sets and reads its own third-party cookies there.", "Provider: books.google.com (Google). Service: Google Books (see Google's Privacy Policy at policies.google.com/privacy). Type: third-party cookies, set by Google, not by LiteraryWorm; we can't read them.", "We mark Google Books covers and the preview as essential, so they show even if you decline other cookies in Consent Preferences. To stop Google's cookies, block third-party cookies in your browser's settings: LiteraryWorm keeps working, and covers still show. Kids profiles show only LiteraryWorm's own titles, so they don't load Google Books.", "The audiobook recordings streamed from the Internet Archive load from that service too, and it may set or read its own cookies under its own policy.$lw$)::jsonb, updated_at = now()
where slug = $lw$cookies$lw$ and strpos(sections::text, $lw$Some book covers from Google Books, the Google Books preview on some book pages (only when you open it), and the audiobook recordings streamed from the Internet Archive, load from those services. When your browser fetches them, those services may set or read their own cookies under their own policies. Blocking third-party cookies in your browser doesn't stop LiteraryWorm working.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$LiteraryWorm uses only essential cookies and similar technologies. We don't use cookies$lw$, $lw$LiteraryWorm uses only essential cookies and similar technologies, including the third-party cookies Google sets from books.google.com when Google Books covers and previews load, because we use the Google Books API. We don't use cookies$lw$)::jsonb, updated_at = now()
where slug = $lw$cookies$lw$ and strpos(sections::text, $lw$LiteraryWorm uses only essential cookies and similar technologies. We don't use cookies$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$to place cookies or web beacons on your computer or mobile device through our Website to serve or measure advertising.$lw$, $lw$to place cookies or web beacons on your computer or mobile device through our Website to serve or measure advertising. Google's cookies from books.google.com are set under Google's own policies; we don't use them, and we don't receive them.$lw$)::jsonb, updated_at = now()
where slug = $lw$cookies$lw$ and strpos(sections::text, $lw$to place cookies or web beacons on your computer or mobile device through our Website to serve or measure advertising.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$In Short: We use only essential cookies and similar technologies, described in our Cookie Policy.$lw$, $lw$In Short: We use only essential cookies and similar technologies, described in our Cookie Policy. Because we use the Google Books API, Google sets third-party cookies from books.google.com when book covers and previews load.$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$In Short: We use only essential cookies and similar technologies, described in our Cookie Policy.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$and we don't use Google Analytics or any other analytics or advertising service.$lw$, $lw$and we don't use Google Analytics or any other analytics or advertising service.", "Google Books covers and the Google Books preview load from books.google.com, and Google sets its own third-party cookies there, under Google's Privacy Policy. We don't receive them. To stop them, block third-party cookies in your browser; LiteraryWorm keeps working.$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$and we don't use Google Analytics or any other analytics or advertising service.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$the names of authors people follow, never who's asking. LibriVox recordings stream$lw$, $lw$the names of authors people follow, never who's asking. Book covers and the Google Books preview load from books.google.com directly in your browser, and Google sets third-party cookies there (see the Cookie Policy). LibriVox recordings stream$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$the names of authors people follow, never who's asking. LibriVox recordings stream$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$LiteraryWorm uses the Google Books API to show book details and covers when you browse and search, so you can find almost any book, save it to your library and write about it.$lw$, $lw$LiteraryWorm uses the Google Books API to show book details and covers when you browse and search, so you can find almost any book, save it to your library and write about it.", "Those covers, and the Google Books preview on some book pages, load from books.google.com, so Google sets its own third-party cookies on our website when they load. The Cookie Policy explains them, and blocking third-party cookies in your browser stops them without stopping LiteraryWorm.$lw$)::jsonb, updated_at = now()
where slug = $lw$help$lw$ and strpos(sections::text, $lw$LiteraryWorm uses the Google Books API to show book details and covers when you browse and search, so you can find almost any book, save it to your library and write about it.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$There's no advertising on LiteraryWorm, and we don't use analytics or advertising trackers.$lw$, $lw$There's no advertising on LiteraryWorm, and we don't use analytics or advertising trackers.", "Kids profiles show only LiteraryWorm's own titles, so Google Books covers and previews, and the third-party cookies Google sets from books.google.com with them, don't load there.$lw$)::jsonb, updated_at = now()
where slug = $lw$childrens-privacy$lw$ and strpos(sections::text, $lw$There's no advertising on LiteraryWorm, and we don't use analytics or advertising trackers.$lw$) > 0;

insert into public.changelog_entries (released_on, version, kind, title, body, major)
select $lw$2026-11-01$lw$::date, $lw$2026.11$lw$, $lw$update$lw$, $lw$Google Books cookies, said plainly$lw$, $lw$Because LiteraryWorm uses the Google Books API, covers of books from Google Books, and the Google Books preview on some book pages, load from books.google.com, and Google sets its own third-party cookies on our website when they do. The Cookie Policy, Privacy Policy, Help, the FAQ and the Children's Privacy Notice now say so, and how to block them; Kids profiles don't load Google Books.$lw$, false
where not exists (select 1 from public.changelog_entries c where c.title = $lw$Google Books cookies, said plainly$lw$ and c.version = $lw$2026.11$lw$);
